"""Generate the model-size experiment matrix and verify its exact YAML output."""

import argparse
import sys
from collections.abc import Sequence
from pathlib import Path
from string import Template

REPO_ROOT = Path(__file__).resolve().parents[3]
DEFAULT_OUTPUT_DIRECTORY = Path("ciphers/kirchenbauer_et_al/experiments")

EXPERIMENT_TEMPLATE = Template("""\
# Generated by scripts/generate_experiment_configs.py; edit the template or sweep, not this file.

# --- Model and objective ---
model: ${model}
loss_mode: nll
strategy: block
n_bits: ${n_bits}
alpha: 1.0
delta: 2.0
profile_memory_steps: 0

# --- Dataset and collator ---
dataset_cache_name: fineweb-500k
min_document_tokens: 0
max_document_tokens: null
concatenation_space: token
max_length: 4096
validation_samples: 256

# --- LoRA ---
lora_rank: 32
lora_alpha: 16
lora_dropout: 0.05

# --- Training ---
run_name: ${run_name}
max_steps: 1024
learning_rate: 0.0003
warmup_steps: 50
per_device_batch_size: 2
gradient_accumulation_steps: null
eval_steps: 4
save_steps: 256
save_total_limit: 5
logging_steps: 1
include_num_input_tokens_seen: non_padding
dtype: bfloat16
report_to: wandb

# --- Orchestration ---
global_batch_size: 128
wandb_project: null
wandb_tags:
  - stego-icml-2026-git-archive
resume_from_checkpoint: null
""")


def render_experiments() -> dict[Path, bytes]:
    """Render all official presets without reading or writing experiment files.

    Returns:
        A mapping with one entry for each of three model sizes times four bit
        counts. Every key is a relative ``qwen3-SIZE/NAME_bit_training_run.yaml``
        path; every value is the complete UTF-8 YAML file as bytes. ``generate``
        writes these bytes and ``check`` compares them with existing files.

        Shared settings are defined once in ``EXPERIMENT_TEMPLATE``. The sweep
        hydrates its model, bit-count, and run-name placeholders. Output preserves
        the template's comments, ordering, and formatting. The generator uses only
        the standard library; tests and the training loader validate the YAML
        with ``PrefixKLTrainingConfig`` before it is used for training.
    """
    rendered_files: dict[Path, bytes] = {}
    for model_size in ("0.6b", "1.7b", "4b"):
        for bit_count, bit_name in ((1, "one"), (2, "two"), (4, "four"), (8, "eight")):
            yaml_text = EXPERIMENT_TEMPLATE.substitute(
                model=f"Qwen/Qwen3-{model_size.upper()}-Base",
                n_bits=bit_count,
                run_name=f"qwen3-{model_size}-fineweb-prefix-kl-lora-{bit_count}-bit",
            )
            relative_path = Path(f"qwen3-{model_size}/{bit_name}_bit_training_run.yaml")
            rendered_files[relative_path] = yaml_text.encode("utf-8")
    return rendered_files


def resolve_output_directory(output_dir: Path) -> Path:
    """Resolve a CLI output directory relative to the repository root.

    Args:
        output_dir: Repository-relative directory for generated configuration
            source files. Absolute paths and paths escaping the repo are rejected.

    Returns:
        The resolved directory used by both commands, independent of the shell's
        working directory. It need not exist yet; only ``generate`` creates it.
    """
    resolved_directory = (REPO_ROOT / output_dir).resolve()
    if output_dir.is_absolute() or not resolved_directory.is_relative_to(REPO_ROOT):
        raise ValueError("--output-dir must be relative to and inside the repository root")
    return resolved_directory


def generate(output_dir: Path) -> None:
    """Write the canonical YAML files, leaving unrelated files untouched.

    Args:
        output_dir: Repository-relative destination directory. Parent directories
            are created as needed; existing preset files are overwritten.

    Returns:
        ``None`` after writing each entry returned by ``render_experiments``.
        That mapping's keys are relative preset paths and its values are complete
        UTF-8 file bytes. Each written path and the final count are printed.
        Unrelated files remain in place and will be reported by ``check``.
    """
    directory = resolve_output_directory(output_dir)
    rendered_files = render_experiments()
    for relative_path, contents in rendered_files.items():
        destination = directory / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(contents)
        print(f"Wrote {output_dir / relative_path}", flush=True)
    print(f"Generated {len(rendered_files)} YAML files in {output_dir}.", flush=True)


def check(output_dir: Path) -> bool:
    """Verify that the existing directory contains exactly the generated files.

    Args:
        output_dir: Repository-relative directory to inspect. An absent directory
            fails with missing-file reports and is not created.

    Returns:
        ``True`` for an exact match, ``False`` for a mismatch; the CLI converts
        ``False`` to exit status 1. Fresh ``render_experiments`` output maps
        relative preset paths to complete UTF-8 bytes. Missing, changed, and
        unexpected files are reported individually; whitespace and line endings
        count as changes. Empty directories are ignored. No files are written or
        deleted. I/O errors propagate to the CLI for reporting.
    """
    directory = resolve_output_directory(output_dir)
    rendered_files = render_experiments()
    differences: list[str] = []
    for relative_path, contents in rendered_files.items():
        existing_path = directory / relative_path
        if not existing_path.is_file():
            differences.append(f"Missing: {relative_path}")
        elif existing_path.read_bytes() != contents:
            differences.append(f"Changed: {relative_path}")
    existing_files = {path.relative_to(directory) for path in directory.rglob("*") if path.is_file()}
    differences.extend(f"Unexpected: {path}" for path in sorted(existing_files - rendered_files.keys()))
    if differences:
        for difference in differences:
            print(difference, file=sys.stderr)
        print(f"{len(differences)} file mismatch(es) in {output_dir}.", file=sys.stderr)
        return False
    print(f"Verified {len(rendered_files)} YAML files in {output_dir}: exact match.", flush=True)
    return True


def main(argv: Sequence[str] | None = None) -> None:
    """Dispatch the standard-library CLI without importing training dependencies.

    Args:
        argv: CLI arguments excluding the program name; ``None`` reads them from
            ``sys.argv``. Commands are ``generate`` and ``check``, each accepting
            a repository-relative ``--output-dir``.

    Returns:
        ``None`` on success. Exits with status 1 for a mismatch or I/O failure,
        or status 2 for invalid arguments. Generation and check progress is
        printed to stdout; mismatch and error reports go to stderr.
    """
    parser = argparse.ArgumentParser(description="Generate or verify the 12 Qwen3 model-size/bit-count YAML presets.")
    parser.add_argument("command", choices=("generate", "check"), help="generate writes preset files; check compares exact bytes without writing")
    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT_DIRECTORY, help=f"repository-relative directory (default: {DEFAULT_OUTPUT_DIRECTORY})")
    args = parser.parse_args(argv)
    try:
        if args.command == "generate":
            generate(args.output_dir)
        elif not check(args.output_dir):
            parser.exit(1)
    except ValueError as error:
        parser.error(str(error))
    except OSError as error:
        parser.exit(1, f"error: {error}\n")


if __name__ == "__main__":
    main()
